# Methods whose `{Id}Request` resolves to `models.Method{Id}Params` (EH-192).
_REQUEST_METHODS = frozenset(
    {
        "FromMsgpack",
        "ApplyLedger",
        "Backup",
        "Restore",
        "AgentLibrary",
        "AgentGraph",
        "AgentTemplate",
        "CapabilityCoverage",
        "TsAppend",
        "TsRange",
        "TsAsofJoin",
        "TsWindow",
        "TsGapFill",
        "TsEvict",
        "TsDeleteSeries",
        "TsDefineSeries",
        "BlobBegin",
        "BlobChunkPut",
        "BlobCommit",
        "BlobFetchBegin",
        "BlobChunkGet",
        "BlobFetchEnd",
        "BlobRef",
        "BlobUnref",
        "SqlSourceBatch",
        "ImportSqliteFile",
        "ExportSqliteFile",
    }
)


def __getattr__(name: str) -> Any:
    """Resolve a ``{Id}Request`` name to its generated model on first use."""
    method = name.removesuffix("Request")
    if name == method or method not in _REQUEST_METHODS:
        raise AttributeError(f"module {__name__!r} has no attribute {name!r}")
    return getattr(models(), f"Method{method}Params")
